#!/usr/bin/env node
// Split the monolithic CLAUDE.md into the files that replace it (AGENTS.md plan,
// .claude/outputs/CCR-CLAUDE-USAGE-OPTIMIZATION-2026-10-11.md, Phase 2).
//
// Transitional: it exists so the AGENTS.md branch can be rebased onto main while
// main keeps adding to CLAUDE.md §3. Delete it (and its test) once the split has
// merged; from then on the generated files are edited directly.
//
//   node scripts/brain/split-claude-md.mjs --from <monolith CLAUDE.md> [--root .] [--accept]
//
// Writes, verbatim from the monolith:
//   docs/brain/PRODUCT.md       <- §1 Architecture Decisions + §2 Ecosystem
//   docs/brain/ROLE-STATE.md    <- §3 Scrum Team, role current states
//   docs/brain/CONSTRAINTS.md   <- §4 Known Constraints
//   docs/brain/STORY-FORMAT.md  <- §6 Story Format
// The other parts (preamble, §5, §7, §8) were rewritten by hand into
// AGENTS.md and the slim CLAUDE.md. Their hashes are kept in
// docs/brain/.split-fingerprint.json; when main changes one of them the script
// still writes the generated files, names the changed parts and exits 3, so the
// change gets ported by hand. --accept records the new hashes after porting.
//
// Exit codes: 0 ok, 2 bad input, 3 hand-ported parts changed upstream.

import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

const EXPECTED = ['1', '2', '3', '4', '5', '6', '7', '8'];
const GENERATED = [
  {
    file: 'docs/brain/PRODUCT.md',
    parts: ['1', '2'],
    title: 'Product context (from CLAUDE.md §1–§2)',
  },
  {
    file: 'docs/brain/ROLE-STATE.md',
    parts: ['3'],
    title: 'Role current states (from CLAUDE.md §3)',
  },
  {
    file: 'docs/brain/CONSTRAINTS.md',
    parts: ['4'],
    title: 'Known constraints (from CLAUDE.md §4)',
  },
  { file: 'docs/brain/STORY-FORMAT.md', parts: ['6'], title: 'Story format (from CLAUDE.md §6)' },
];
const HAND_PORTED = ['preamble', '5', '7', '8'];
const FINGERPRINT = 'docs/brain/.split-fingerprint.json';

function args(argv) {
  const out = { root: process.cwd(), accept: false };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--from') out.from = argv[++i];
    else if (argv[i] === '--root') out.root = argv[++i];
    else if (argv[i] === '--accept') out.accept = true;
  }
  return out;
}

function splitSections(text) {
  const normalised = text.replace(/\r\n/g, '\n');
  const heading = /^## (\d+)\. .*$/gm;
  const marks = [...normalised.matchAll(heading)].map((m) => ({ n: m[1], at: m.index }));
  if (marks.length === 0)
    throw new Error('no "## N. " sections found; is this the monolithic CLAUDE.md?');
  const parts = { preamble: normalised.slice(0, marks[0].at) };
  marks.forEach((m, i) => {
    parts[m.n] = normalised.slice(m.at, i + 1 < marks.length ? marks[i + 1].at : undefined);
  });
  const found = marks.map((m) => m.n);
  const missing = EXPECTED.filter((n) => !found.includes(n));
  const extra = found.filter((n) => !EXPECTED.includes(n));
  if (missing.length || extra.length) {
    throw new Error(
      `section set changed (missing: ${missing.join(',') || 'none'}; new: ${extra.join(',') || 'none'}); update this script`
    );
  }
  return parts;
}

const hash = (s) => createHash('sha256').update(s.trim()).digest('hex').slice(0, 16);

function generated(title, body) {
  return (
    `# ${title}\n\n` +
    '> Moved out of the root `CLAUDE.md` so it is read when needed instead of on every turn.\n' +
    '> Generated by `scripts/brain/split-claude-md.mjs` while the AGENTS.md branch is open;\n' +
    '> after that branch merges, edit this file directly.\n\n' +
    body.replace(/\n+---\s*\n*$/, '\n').trimEnd() +
    '\n'
  );
}

function main() {
  const opt = args(process.argv.slice(2));
  if (!opt.from || !existsSync(opt.from)) {
    process.stderr.write(
      'usage: split-claude-md.mjs --from <monolith CLAUDE.md> [--root .] [--accept]\n'
    );
    process.exit(2);
  }
  let parts;
  try {
    parts = splitSections(readFileSync(opt.from, 'utf8'));
  } catch (e) {
    process.stderr.write(`split-claude-md: ${e.message}\n`);
    process.exit(2);
  }

  for (const g of GENERATED) {
    const out = join(opt.root, g.file);
    mkdirSync(dirname(out), { recursive: true });
    writeFileSync(out, generated(g.title, g.parts.map((p) => parts[p]).join('')));
    process.stdout.write(`wrote ${g.file}\n`);
  }

  const now = Object.fromEntries(HAND_PORTED.map((p) => [p, hash(parts[p])]));
  const fpFile = join(opt.root, FINGERPRINT);
  const before = existsSync(fpFile) ? JSON.parse(readFileSync(fpFile, 'utf8')) : null;
  if (!before || opt.accept) {
    writeFileSync(fpFile, JSON.stringify(now, null, 2) + '\n');
    process.stdout.write(`${before ? 'accepted' : 'recorded'} fingerprint of hand-ported parts\n`);
    process.exit(0);
  }
  const changed = HAND_PORTED.filter((p) => before[p] !== now[p]);
  if (changed.length) {
    process.stdout.write(
      `hand-ported parts changed on main: ${changed.map((p) => (p === 'preamble' ? 'preamble' : `§${p}`)).join(', ')}\n` +
        'Port those changes into AGENTS.md / CLAUDE.md, then re-run with --accept.\n'
    );
    process.exit(3);
  }
  process.stdout.write('hand-ported parts unchanged\n');
}

main();
